import { onlyChangesUnrelatedAttrs } from './../../ricos-common-plugins/transaction-predicates/only-changes-unrelated-attrs.js';
import type { Group, RicosExtension } from './../../ricos-types/index.js';
import { Mark_Type } from './../../ricos-types/index.js';
import { createRicosMarkExtension } from './../../plugin-commons/index.js';

import { findHashTag } from './find-hash-tag.js';

export const tiptapExtensions: RicosExtension[] = [
  createRicosMarkExtension({
    type: 'mark',
    groups: [] as Group[],
    name: Mark_Type.HASHTAG,
    createExtensionConfig({ Plugin }) {
      return {
        name: this.name,
        addProseMirrorPlugins() {
          return [
            new Plugin({
              state: {
                init(_, { doc }) {
                  return findHashTag(doc);
                },
                apply(transaction, oldState) {
                  if (!transaction.docChanged) {
                    return oldState;
                  }
                  // Reads text + marks only, no node attrs.
                  if (onlyChangesUnrelatedAttrs(transaction)) {
                    return oldState;
                  }
                  return findHashTag(transaction.doc);
                },
              },
              props: {
                decorations(state) {
                  return this.getState(state);
                },
              },
            }),
          ];
        },
      };
    },
  }),
];
